}

export type Snapshot = {
  cwd: string
  rows: PortRow[]
  others: number
  updatedAt: number
  error: string | null
}

declare module 'claude-code' {
  interface PluginState {
    workbench: {
      snapshot: Snapshot | null
      confirming: number | null
    }
  }
